SELECT jsonb_build_object(
'columns', (SELECT jsonb_agg(to_jsonb(x) ORDER BY x.table_name,x.ordinal_position) FROM (SELECT table_name,ordinal_position,column_name,data_type,udt_name,character_maximum_length,numeric_precision,numeric_scale,datetime_precision,is_nullable,column_default,is_identity,identity_generation,is_generated,generation_expression FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('members','data_cleaner_history','seating_desks','user_notifications')) x),
'constraints', (SELECT jsonb_agg(to_jsonb(x) ORDER BY x.table_name,x.name) FROM (SELECT c.relname AS table_name,k.conname AS name,k.contype AS type,pg_get_constraintdef(k.oid) AS definition,k.convalidated AS validated,k.condeferrable AS deferrable,k.condeferred AS deferred FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('members','data_cleaner_history','seating_desks','user_notifications')) x),
'indexes', (SELECT jsonb_agg(to_jsonb(x) ORDER BY x.tablename,x.indexname) FROM (SELECT tablename,indexname,indexdef FROM pg_indexes WHERE schemaname='public' AND tablename IN ('members','data_cleaner_history','seating_desks','user_notifications')) x),
'policies', (SELECT jsonb_agg(to_jsonb(x) ORDER BY x.tablename,x.policyname) FROM (SELECT tablename,policyname,permissive,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname='public' AND tablename IN ('members','data_cleaner_history','seating_desks','user_notifications')) x),
'tables', (SELECT jsonb_agg(to_jsonb(x) ORDER BY x.table_name) FROM (SELECT c.relname AS table_name,pg_get_userbyid(c.relowner) AS owner,c.relrowsecurity AS rls,c.relforcerowsecurity AS force_rls,EXISTS(SELECT 1 FROM pg_publication_tables p WHERE p.schemaname='public' AND p.tablename=c.relname AND p.pubname='supabase_realtime') AS realtime FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('members','data_cleaner_history','seating_desks','user_notifications') AND c.relkind='r') x),
'triggers', (SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.table_name,x.name),'[]'::jsonb) FROM (SELECT c.relname AS table_name,t.tgname AS name,pg_get_triggerdef(t.oid) AS definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND n.nspname='public' AND c.relname IN ('members','data_cleaner_history','seating_desks','user_notifications')) x)
) AS snapshot;
